import os
import glob
from collections import Counter

def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.isdir(directory):
        raise OSError(f"The specified directory '{directory}' does not exist.")

    file_counter = Counter()

    for ext in extensions:
        pattern = os.path.join(directory, f"**", f"*{ext}")
        for file_path in glob.glob(pattern, recursive=True):
            if os.path.isfile(file_path):
                file_counter[ext] += 1

    if not keep_zero:
        file_counter = {k: v for k, v in file_counter.items() if v > 0}
        file_counter = Counter(file_counter)

    return file_counter

