def task_func(file_path: str) -> pd.DataFrame:
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The specified log file '{file_path}' does not exist.")

    log_pattern = re.compile(r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.\d{6}) - (\w+) - (.+)')
    logs_data = []

    with open(file_path, 'r') as file:
        for line in file:
            match = log_pattern.match(line.strip())
            if match:
                timestamp, level, message = match.groups()
                logs_data.append({'Timestamp': timestamp, 'Level': level, 'Message': message})

    return pd.DataFrame(logs_data, columns=['Timestamp', 'Level', 'Message'])

