import random
import math

def task_func(LETTERS=[chr(i) for i in range(97, 123)]):
    # Create a dictionary with letters as keys and random integer lists as values
    letter_dict = {letter: [random.randint(0, 100) for _ in range(random.randint(1, 11))] for letter in LETTERS}

    # Function to calculate population standard deviation
    def population_stddev(lst):
        if len(lst) == 1:
            return 0.0  # Standard deviation is 0 for a single element
        mean = sum(lst) / len(lst)
        squared_diffs = [(x - mean) ** 2 for x in lst]
        sum_squared_diffs = sum(squared_diffs)
        variance = sum_squared_diffs / len(lst)
        return math.sqrt(variance)

    # Calculate standard deviations for each list and create the result dictionary
    stddev_dict = {letter: population_stddev(int_list) for letter, int_list in letter_dict.items()}

    return stddev_dict

